+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridVariant;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationVariant;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>(ContactMessage.class, false);
+
+    private boolean clearingAfterSend;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        addClassName("contact-view");
+        setPadding(true);
+        setSpacing(false);
+
+        H1 heading = new H1("Contact");
+        heading.addClassName("contact-title");
+
+        RouterLink about = new RouterLink("About", AboutView.class);
+        about.addClassName("about-link");
+
+        configureFields();
+        FormLayout form = createForm();
+        configureGrid();
+
+        add(heading, about, form, messages);
+    }
+
+    private void configureFields() {
+        message.setMinHeight("9rem");
+
+        name.addValueChangeListener(event -> fieldEdited(name));
+        email.addValueChangeListener(event -> fieldEdited(email));
+        phone.addValueChangeListener(event -> fieldEdited(phone));
+        message.addValueChangeListener(event -> fieldEdited(message));
+
+        send.addThemeVariants(ButtonVariant.PRIMARY);
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+    }
+
+    private FormLayout createForm() {
+        FormLayout form = new FormLayout();
+        form.addClassNames("contact-form", "aura-surface");
+        form.setAutoResponsive(true);
+        form.setMaxColumns(2);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setColumnWidth("16rem");
+        form.addFormRow(name, email);
+        form.addFormRow(phone);
+        form.addFormRow(message);
+        form.addFormRow(send);
+        return form;
+    }
+
+    private void configureGrid() {
+        messages.addClassName("message-grid");
+        messages.addThemeVariants(GridVariant.NO_BORDER);
+        messages.addColumn(ContactMessage::name)
+                .setHeader("Name")
+                .setAutoWidth(true)
+                .setFlexGrow(0);
+        messages.addColumn(ContactMessage::message)
+                .setHeader("Message")
+                .setFlexGrow(1);
+        messages.setAllRowsVisible(true);
+        refreshMessages();
+    }
+
+    private void fieldEdited(com.vaadin.flow.component.HasValidation field) {
+        if (!clearingAfterSend) {
+            send.setEnabled(true);
+            field.setInvalid(false);
+        }
+    }
+
+    private void sendMessage() {
+        if (!validateForm()) {
+            return;
+        }
+
+        messageStore.save(new ContactMessage(
+                name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        clearForm();
+        send.setEnabled(false);
+
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.SUCCESS);
+    }
+
+    private boolean validateForm() {
+        clearValidation();
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private static void invalidate(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearForm() {
+        clearingAfterSend = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+            clearValidation();
+        } finally {
+            clearingAfterSend = false;
+        }
+    }
+
+    private void refreshMessages() {
+        messages.setItems(messageStore.findAll());
+    }
+
+    private boolean hasDraft() {
+        return !name.getValue().isEmpty()
+                || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) {
+            return;
+        }
+
+        ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard this message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            action.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.PRIMARY);
+
+        dialog.add("You have an unfinished message.");
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
