+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void emptyFormIsEnabledAndShowsExactValidationMessages() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(sendButton().isEnabled());
+        int initialSize = test(find(Grid.class).single()).size();
+
+        test(sendButton()).click();
+
+        assertInvalid(nameField(), "Name is required");
+        assertInvalid(emailField(), "Give an e-mail address or a phone number");
+        assertInvalid(messageField(), "Message is required");
+        assertFalse(find(Notification.class).exists());
+        assertEquals(initialSize, test(find(Grid.class).single()).size());
+    }
+
+    @Test
+    void invalidEmailAndLongMessageKeepTheDraft() {
+        navigate(ContactView.class);
+        test(nameField()).setValue("Taylor");
+        test(emailField()).setValue("not-an-address");
+        test(messageField()).setValue("x".repeat(501));
+
+        test(sendButton()).click();
+
+        assertInvalid(emailField(), "Enter a valid e-mail address");
+        assertInvalid(messageField(), "Message must be at most 500 characters");
+        assertEquals("Taylor", nameField().getValue());
+        assertEquals("x".repeat(501), messageField().getValue());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void enterSendsNewestFirstClearsAndDisablesUntilAnEdit() {
+        navigate(ContactView.class);
+        int initialSize = test(find(Grid.class).single()).size();
+
+        fillValidForm("First sender", "first@example.com", "", "First message");
+        test(sendButton()).click();
+        fillValidForm("Newest sender", "", "555-0100", "Newest message");
+        fireShortcut(Key.ENTER);
+
+        Grid<?> grid = find(Grid.class).single();
+        assertEquals(initialSize + 2, test(grid).size());
+        ContactMessage firstRow = assertInstanceOf(ContactMessage.class, test(grid).getRow(0));
+        assertEquals("Newest sender", firstRow.name());
+        assertEquals("Newest message", firstRow.message());
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageField().getValue());
+        assertFalse(sendButton().isEnabled());
+        assertTrue(find(Notification.class).all().stream()
+                .map(notification -> test(notification).getText())
+                .anyMatch(text -> text.contains("Message sent")));
+
+        test(phoneField()).setValue("1");
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void navigationGuardCanKeepOrDiscardAndSentMessagesPersist() {
+        navigate(ContactView.class);
+        int initialSize = test(find(Grid.class).single()).size();
+        fillValidForm("Persistent sender", "saved@example.com", "", "Stored message");
+        test(sendButton()).click();
+
+        test(find(RouterLink.class).withText("About").single()).navigate();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertEquals(initialSize + 1, test(find(Grid.class).single()).size());
+
+        test(nameField()).setValue("Unfinished");
+        test(find(RouterLink.class).withText("About").single()).navigate();
+        assertTrue(find(Dialog.class).single().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+        assertFalse(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Unfinished", nameField().getValue());
+
+        test(find(RouterLink.class).withText("About").single()).navigate();
+        test(find(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    private void fillValidForm(String name, String email, String phone, String message) {
+        test(nameField()).setValue(name);
+        test(emailField()).setValue(email);
+        test(phoneField()).setValue(phone);
+        test(messageField()).setValue(message);
+    }
+
+    private TextField nameField() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField emailField() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phoneField() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea messageField() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button sendButton() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private static void assertInvalid(com.vaadin.flow.component.HasValidation field,
+            String errorMessage) {
+        assertTrue(field.isInvalid());
+        assertEquals(errorMessage, field.getErrorMessage());
+    }
